--   ultrasonic_a_scan: columns max_x_mm<-Useable Length (mm), max_y_mm<-Useable Width (mm), max_z_mm<-Useable Height (mm)
--     specs keys: is_preferred, overhead_multiplier, machine_manufacturer_location, surface_scan_rate_mm2_per_s, useable_length_mm, useable_width_mm, useable_height_mm, total_overhead_rate_usd_hr, period_overhead_coefficient
