WHERE NOT EXISTS (
  SELECT 1 FROM mhr_records m
  WHERE m.machine_class = v.machine_class
    AND m.location = v.location
    AND lower(trim(m.machine_name)) = lower(trim(v.machine_name))
);

-- ── 2. Capability of the 11 CMM rows migration 806 seeded (matched by
--      benchmark_source_key). Bed Length/Width/Height -> max_x/max_y/max_z,
--      Max Allowable Mass -> max_workpiece_weight_kg. Only NULL columns are filled.
UPDATE mhr_records m
SET max_x_mm                = COALESCE(m.max_x_mm, v.max_x_mm),
    max_y_mm                = COALESCE(m.max_y_mm, v.max_y_mm),
    max_z_mm                = COALESCE(m.max_z_mm, v.max_z_mm),
    max_workpiece_weight_kg = COALESCE(m.max_workpiece_weight_kg, v.max_workpiece_weight_kg),
    capability_source       = COALESCE(m.capability_source, 'imported')
FROM (VALUES
  ($str$CMM Inspection:Axiom Too 1200$str$, 900, 640, 500, 300),
  ($str$CMM Inspection:Axiom Too 1500$str$, 1200, 640, 500, 300),
  ($str$CMM Inspection:Axiom Too 1800$str$, 1500, 640, 500, 300),
  ($str$CMM Inspection:Axiom Too 900$str$, 600, 640, 500, 300),
  ($str$CMM Inspection:Axiom Xtreme 350$str$, 300, 300, 200, 50),
  ($str$CMM Inspection:Axiom Xtreme 500$str$, 400, 400, 270, 50),
  ($str$CMM Inspection:Axiom Zenith 1000$str$, 1000, 1000, 1500, 1500),
  ($str$CMM Inspection:Axiom Zenith 1500$str$, 1500, 1000, 1500, 1500),
  ($str$CMM Inspection:Axiom Zenith 2000$str$, 2000, 1000, 1500, 1500),
  ($str$CMM Inspection:Axiom Zenith 2500$str$, 2500, 1000, 1500, 1500),
  ($str$CMM Inspection:Axiom Zenith 3000$str$, 3000, 1000, 1500, 1500)
) AS v(benchmark_source_key, max_x_mm, max_y_mm, max_z_mm, max_workpiece_weight_kg)
WHERE m.machine_class = 'cmm'
  AND m.benchmark_source_key = v.benchmark_source_key
  AND (m.max_x_mm IS NULL OR m.max_y_mm IS NULL OR m.max_z_mm IS NULL OR m.max_workpiece_weight_kg IS NULL);

-- ── 3. Catalog rows migration 790 seeded (machine_class NULL). Only
--      machine_class is set (plus updated_at on the mapping rows). is_active and
--      roadmap_status are NOT touched: the mapping rows stay inactive, which the
--      chk_machine_class_required CHECK allows with or without a machine_class.
UPDATE process_taxonomy pt
SET machine_class = v.machine_class
FROM (VALUES
  ($str$Carton Forming$str$, $str$carton_forming$str$),
  ($str$Carton Sealing$str$, $str$carton_sealing$str$),
  ($str$CT Scan$str$, $str$ct_scan$str$),
  ($str$Fluorescent Penetrant Testing$str$, $str$fluorescent_penetrant_testing$str$),
  ($str$Hydrostatic Leak Testing$str$, $str$hydrostatic_leak_testing$str$),
  ($str$Magnetic Particle Testing$str$, $str$magnetic_particle_testing$str$),
  ($str$Pack & Load$str$, $str$pack_and_load$str$),
  ($str$Ultrasonic A-Scan$str$, $str$ultrasonic_a_scan$str$),
  ($str$Ultrasonic C-Scan$str$, $str$ultrasonic_c_scan$str$),
  ($str$Ultrasonic Cleaning$str$, $str$ultrasonic_cleaning$str$),
  ($str$Xray Inspection$str$, $str$xray_inspection$str$)
) AS v(process_name, machine_class)
WHERE pt.process_group = 'Other Secondary Processes'
  AND pt.process_name = v.process_name
  AND pt.machine_class IS NULL;

UPDATE process_calculator_mappings pcm
SET machine_class = v.machine_class,
    updated_at = NOW()
FROM (VALUES
  ($str$Carton Forming$str$, $str$carton_forming$str$),
  ($str$Carton Sealing$str$, $str$carton_sealing$str$),
  ($str$CT Scan$str$, $str$ct_scan$str$),
  ($str$Fluorescent Penetrant Testing$str$, $str$fluorescent_penetrant_testing$str$),
  ($str$Hydrostatic Leak Testing$str$, $str$hydrostatic_leak_testing$str$),
  ($str$Magnetic Particle Testing$str$, $str$magnetic_particle_testing$str$),
  ($str$Pack & Load$str$, $str$pack_and_load$str$),
  ($str$Ultrasonic A-Scan$str$, $str$ultrasonic_a_scan$str$),
  ($str$Ultrasonic C-Scan$str$, $str$ultrasonic_c_scan$str$),
  ($str$Ultrasonic Cleaning$str$, $str$ultrasonic_cleaning$str$),
  ($str$Xray Inspection$str$, $str$xray_inspection$str$)
) AS v(operation, machine_class)
WHERE pcm.process_group = 'Other Secondary Processes'
  AND pcm.operation = v.operation
  AND pcm.machine_class IS NULL;

NOTIFY pgrst, 'reload schema';

